<?php /* Widget "Chat Admin/Petugas" (tombol melayang + jendela chat). Dipakai site/footer dan Dashboard Warga (citizen/dashboard). Butuh assets/chat.css. */ ?>
<?php if(!isset($this->feature_gate))$this->load->library('Feature_gate'); if ($this->session->userdata('citizen_id') && $this->feature_gate->link_ok('warga/chat','warga')): ?>
<section class="live-chat-widget" id="live-chat-widget" aria-label="Chat admin" hidden><header><span class="live-chat-widget-avatar">RT<i></i></span><div><strong id="widget-admin-name">Admin/Pengurus RT</strong><small><b></b> <span id="widget-admin-status">Memuat status...</span></small></div><button type="button" id="widget-chat-close" aria-label="Tutup chat">×</button></header><div class="live-chat-widget-messages" id="widget-chat-messages"><div class="widget-chat-empty" id="widget-chat-empty">Belum ada pesan. Mulai percakapan dengan admin atau pengurus.</div></div><form id="widget-chat-form"><input type="hidden" name="admin_id" id="widget-admin-id" value="0"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><textarea name="message" maxlength="2000" rows="1" placeholder="Tulis pesan..." required></textarea><button type="submit" aria-label="Kirim">➤</button></form></section>
<button class="live-chat-float" id="live-chat-toggle" type="button" aria-controls="live-chat-widget" aria-expanded="false"><span class="live-chat-logo" aria-hidden="true"><svg viewBox="0 0 48 48"><path class="chat-logo-bubble" d="M8 8.5h32a4.5 4.5 0 0 1 4.5 4.5v20a4.5 4.5 0 0 1-4.5 4.5H22L12 44v-6.5H8A4.5 4.5 0 0 1 3.5 33V13A4.5 4.5 0 0 1 8 8.5Z"/><path class="chat-logo-smile" d="M15 25c2.2 3.2 5.2 4.8 9 4.8s6.8-1.6 9-4.8"/><circle cx="16" cy="19" r="2.2"/><circle cx="32" cy="19" r="2.2"/><path class="chat-logo-spark" d="m38 3 1.2 3.3L42.5 7l-3.3 1.2L38 11.5l-1.2-3.3L33.5 7l3.3-.7L38 3Z"/></svg></span><span><strong>Chat Admin/Petugas</strong><small><i></i> <b id="widget-online-count">Memuat petugas...</b></small></span></button>
<script>(function(){const widget=document.getElementById('live-chat-widget'),toggle=document.getElementById('live-chat-toggle'),close=document.getElementById('widget-chat-close'),box=document.getElementById('widget-chat-messages'),form=document.getElementById('widget-chat-form'),csrfName='<?= $this->security->get_csrf_token_name() ?>',status=document.getElementById('widget-admin-status');let last=0,busy=false,started=false;function scrollBottom(){box.scrollTop=box.scrollHeight}function setPresence(online){const color=online?'#28cf82':'#aab5c2';widget.querySelector('.live-chat-widget-avatar i').style.background=color;widget.querySelector('header small b').style.background=color;toggle.querySelector('small i').style.background=color}function add(m){if(document.querySelector('[data-widget-message="'+m.id+'"]'))return;document.getElementById('widget-chat-empty')?.remove();const d=document.createElement('div');d.className='widget-chat-bubble '+(m.sender_type==='citizen'?'mine':'theirs');d.dataset.widgetMessage=m.id;const p=document.createElement('p');p.textContent=m.message;const t=document.createElement('time');t.textContent=m.created_at.slice(11,16)+(m.sender_type==='citizen'&&Number(m.is_read)?' ✓✓':'');d.append(p,t);box.append(d);last=Math.max(last,Number(m.id));scrollBottom()}function admins(list){const online=list.filter(a=>Number(a.is_online)),chosen=online[0]||list[0];document.getElementById('widget-online-count').textContent=online.length+' petugas online';setPresence(online.length>0);if(chosen){form.elements.admin_id.value=chosen.id;document.getElementById('widget-admin-name').textContent=chosen.username.replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());status.textContent=Number(chosen.is_online)?'Sedang online':'Sedang offline'}}async function poll(){if(busy)return;try{const r=await fetch('<?= site_url('warga/chat/pesan') ?>?after='+last,{headers:{'X-Requested-With':'XMLHttpRequest'}});if(!r.ok)return;const j=await r.json();j.messages.forEach(add);admins(j.admins);form.elements[csrfName].value=j.csrf}catch(e){status.textContent='Tidak dapat terhubung';setPresence(false)}}function open(){widget.hidden=false;toggle.setAttribute('aria-expanded','true');started=true;poll();scrollBottom();form.elements.message.focus()}function shut(){widget.hidden=true;toggle.setAttribute('aria-expanded','false')}toggle.addEventListener('click',()=>widget.hidden?open():shut());close.addEventListener('click',shut);form.addEventListener('submit',async e=>{e.preventDefault();busy=true;try{const r=await fetch('<?= site_url('warga/chat/kirim') ?>',{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}});if(!r.ok)throw Error();const j=await r.json();form.elements[csrfName].value=j.csrf;form.elements.message.value=''}catch(e){alert('Pesan belum berhasil dikirim.')}finally{busy=false;poll()}});form.elements.message.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit()}});if(location.hash==='#live-chat')open();poll();setInterval(poll,5000)})();</script>
<?php endif; ?>
